function alienContactVisible(k){return !!tile(k)?.known&&s.players.some(p=>!p.captive&&!p.boarded&&dist(p.pos,k)<=2)}
function alienRevealed(k){return !!tile(k)?.known&&s.players.some(p=>!p.captive&&!p.boarded&&dist(p.pos,k)===1)}
