function fingerprintMarkup(){return `<svg viewBox="0 0 100 112" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M9 58C6 28 23 9 48 8C76 6 95 26 94 53"/><path d="M8 69C5 87 13 99 20 104"/><path d="M17 68C10 37 23 17 48 16C72 14 88 32 86 56C85 77 79 96 72 106"/><path d="M23 102C17 87 16 74 17 68"/><path d="M29 103C21 87 21 73 23 56C25 34 34 23 50 23C69 22 81 38 79 58C77 80 72 95 65 108"/><path d="M36 105C28 88 27 73 30 55C32 38 39 30 51 30C66 30 74 41 72 59C70 79 63 95 59 108"/><path d="M43 106C35 88 34 72 37 54C39 42 44 37 52 37C62 37 67 46 65 60C63 78 55 93 54 106"/><path d="M49 106C42 87 41 72 44 55C45 47 48 44 53 44C59 44 61 50 58 63C55 77 49 85 50 95"/><path d="M51 55C49 64 48 73 49 79"/><path d="M94 64C92 83 84 99 79 105"/><path d="M11 42C14 21 26 12 37 10"/></g></svg>`}
function handoffScreen(){const loading=!!ui.handoffLoading,elapsed=Math.max(0,performance.now()-(ui.handoffStarted||0));return `<div class="handoff-terminal ${loading?'authenticating':'handoff-power-up'}"><small>PERSONNEL TERMINAL</small><span class="alien-emblem">◈</span><strong>THE LAST SHIP</strong>${loading?`<div class="fingerprint-scan">${fingerprintMarkup()}</div><h3>AUTHENTICATING…</h3><div class="authentication-bar" role="progressbar" aria-label="Authenticating next player"><span style="animation-delay:-${elapsed}ms"></span></div><small>LOADING PERSONNEL RECORD</small>`:`<h3>PASS THE IPAD</h3><p>NEXT PLAYER<br><b>${esc(rank(s.turn))} ${esc(me().name.toUpperCase())}</b></p><button class="fingerprint-button launch-ready" data-act="fingerprint" aria-label="Identify next player">${fingerprintMarkup()}<span>PRESS TO IDENTIFY</span></button>`}</div>`}
function handoffBoard(){return `<main class="layout"><section class="board"><canvas class="terrain-canvas" width="820" height="614" aria-hidden="true"></canvas>${board()}<div class="art-warning" hidden></div><button class="sound-switch board-sound" data-act="toggleSound" aria-label="Toggle all sound">${soundOn?'SOUND ON':'SOUND OFF'}</button><button class="abort-mission" data-act="abortMission" aria-label="Abort mission and return to title screen">ABORT MISSION</button>${trackerMarkup()}</section><aside class="side player-flip crt-player" style="--player-color:#a9ef99"><div class="flip-inner is-back"><div class="flip-face flip-front"></div><div class="flip-face flip-back">${s.phase==='handoff'?handoffScreen():'<span class="alien-emblem">◈</span><strong>THE LAST SHIP</strong><span>Awaiting next player</span>'}</div></div></aside></main>`}
function heartMonitor(){let p=me(),d=dist(p.pos,nearestAlien(p.pos)),level=p.captive||d<=1?'critical':d===2?'rapid':d===3?'elevated':'steady',info={steady:['STEADY',62],elevated:['ELEVATED',78],rapid:['RAPID',104],critical:['CRITICAL',132]}[level];
 let pulse='M0 40 L66 40 72 37 78 43 86 40 100 40 108 51 116 13 124 58 132 40 146 40 152 37 159 43 166 40 240 40';
 return `<div class="heart-monitor ${level}" style="--beat-time:${60/info[1]}s" role="img" aria-label="${esc(p.name)} heart rate ${info[1]} beats per minute, ${info[0].toLowerCase()} alien proximity"><div class="monitor-title"><span>BIOSUIT · HEART RATE</span><strong>${info[1]} <small>BPM</small></strong></div><div class="monitor-screen"><svg viewBox="0 0 240 80" preserveAspectRatio="none" aria-hidden="true"><path d="${pulse}"><animate attributeName="d" dur="${60/info[1]}s" repeatCount="indefinite" values="M0 40 L66 40 72 40 78 40 86 40 100 40 108 40 116 40 124 40 132 40 146 40 152 40 159 40 166 40 240 40;${pulse};${pulse};M0 40 L66 40 72 40 78 40 86 40 100 40 108 40 116 40 124 40 132 40 146 40 152 40 159 40 166 40 240 40" keyTimes="0;.15;.4;1"/></path></svg><span class="scan-line"></span></div><div class="monitor-foot"><span class="status-light"></span>${info[0]}<span class="monitor-foot-right">LIFE SIGNS</span></div></div>`}
function rememberRoster(){const rows=[...document.querySelectorAll('#names .field')];if(rows.length)ui.roster=rows.map(row=>({name:row.querySelector('input').value,voice:row.querySelector('[data-voice]').dataset.voice}))}
function fieldManual(){return `<div class="overlay rules-overlay" role="dialog" aria-modal="true" aria-labelledby="rules-title"><div class="card crt rules-window"><header><p class="order-classification">COLONIAL MARINES · FIELD MANUAL</p><h2 id="rules-title">FIELD MANUAL</h2><button class="order-ack manual-close" data-act="closeRules">CLOSE MANUAL</button></header><div class="rules-scroll" tabindex="0">
<nav class="manual-nav" aria-label="Manual sections"><a href="#manual-story">Mission</a><a href="#manual-turns">Your turn</a><a href="#manual-tiles">Tile key</a><a href="#manual-equipment">Equipment</a><a href="#manual-transfer">Pass &amp; scan</a><a href="#manual-launch">Extraction</a></nav>
<section id="manual-story"><h3>THE RESCUE MISSION</h3><p>A scientific expedition has gone silent on a hostile alien world. Your Colonial Marine squad arrives by APC with orders to find the two missing scientists and bring them back alive. The Dropship is waiting beyond the landing zone. Between you and safety lie unstable bridges, spore fields, strange Gravity Wells and a creature hunting across the valley.</p><p>You have <strong>nine hours</strong> before the extraction window closes. Each completed round costs one hour. Explore the terrain, locate the scientists, escort them to the staging area and deliver them to the Dropship. Work together, share equipment and decide when to leave.</p><p>But Weyland-Yutani has sent an insider with a second mission. One randomly selected Marine is secretly the <strong>Company Representative</strong>. Alongside recovering the scientists, the Company wants a living specimen: an <strong>ovomorph (alien egg)</strong>, or an implanted organism inside an impregnated passenger. The representative receives private orders and can interfere with the rescue.</p><div class="manual-callout"><strong>CREW VICTORY</strong><p>Extract both scientists with at least one Marine, and leave the egg and every impregnated passenger off the departing ship.</p><strong>COMPANY VICTORY</strong><p>An egg or impregnated passenger leaves aboard the ship—even if the representative stays behind.</p></div><p>If every Marine is captured, the Alien wins. If time runs out without both scientists and an eligible Marine aboard, the mission fails.</p></section>
<section id="manual-turns"><h3>SET UP &amp; TAKE YOUR TURN</h3><p>Play with 4–6 Marines, passing the iPad between players. All start as Marines; one player is secretly assigned as the Company Representative in round two. Their tab turns red and their classified mission opens after fingerprint authentication. Enter names using the green keyboard and choose each player’s male or female capture voice. The first four roles are Sergeant (Jetpack), Weapons Tech (Sentry Gun), Medic (Med Evac) and Science Officer (Flare). Additional players repeat that role order. Everyone starts at the APC with their role’s item.</p><p>Pass the iPad at turn handover. Press the fingerprint button to authenticate and open your player tab. Keep classified orders private. On a normal free turn you have <strong>two moves and one action</strong>. Movement, actions and equipment use can happen in any order.</p><ol><li><strong>Move:</strong> tap an adjacent eligible tile. Each step spends one move and permanently reveals that tile. Arrival may trigger its terrain effect, a discovery or an event.</li><li><strong>Act:</strong> use an available button to search, deliver a scientist, scan, pass or take equipment, rescue a captive or perform another action. Most of these spend your one action.</li><li><strong>Use equipment:</strong> press Use, select a target if requested, then Confirm. Using an item consumes it but costs no action—even after your action is spent. Med Evac and Sentry Gun use your current location and need no target selection.</li><li><strong>End Turn:</strong> the tab powers off, stays black for one second, then powers up to the green fingerprint handover. Every currently playable button pulses, including End Turn whenever it is available. Unused moves and actions are lost. Once the round ends, the alien moves up to two tiles and one hour passes.</li></ol><p>Eligible target tiles pulse translucent red. Select a tile, then confirm or cancel. You can carry <strong>two inventory items</strong> and escort <strong>one scientist</strong> separately. Facehugger injury and some events change your normal turn allowances.</p></section>
<section id="manual-tiles"><h3>VISUAL TILE KEY</h3><p>Unexplored tiles are dark. Moving onto a tile reveals it. A flare also permanently reveals its landing tile.</p><div class="manual-tile-grid"><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Open ground tile" style="background-position:-0px 0"></span><div><h4>Open ground</h4><p>Normal movement; the clear centre holds your Marine.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Hard cover tile" style="background-position:-160px 0"></span><div><h4>Hard cover</h4><p>Protects against normal stalking targets. Noise, lures and direct contact can still put you at risk.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Spore field tile" style="background-position:-320px 0"></span><div><h4>Spore field</h4><p>Entering makes noise and draws the alien. The separate Spore Burst event also stops movement.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Bridge tile" style="background-position:-480px 0"></span><div><h4>Bridge</h4><p>Cross normally. Seismic Shift may collapse an eligible empty bridge; players cannot collapse bridges manually.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Collapsed bridge tile" style="background-position:-640px 0"></span><div><h4>Collapsed bridge</h4><p>Impassable to Marines and aliens; cannot be an equipment target.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Blue Gravity Well tile" style="background-position:-800px 0"></span><div><h4>Blue Gravity Well</h4><p>Entering transports you to the other blue well and reveals both.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Green Gravity Well tile" style="background-position:-960px 0"></span><div><h4>Green Gravity Well</h4><p>Entering transports you to the other green well and reveals both.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Event tile tile" style="background-position:-1120px 0"></span><div><h4>Event tile</h4><p>Draws a new event on every entry, including revisits.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Equipment cache tile" style="background-position:-1280px 0"></span><div><h4>Equipment cache</h4><p>Search here for equipment. Flashing blue lights mark available equipment.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="PDT locator tile" style="background-position:-1440px 0"></span><div><h4>PDT locator</h4><p>Search for a scientist’s Personal Data Transmitter. Some signals are decoys.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Alien nest tile" style="background-position:-1600px 0"></span><div><h4>Alien nest</h4><p>Alien starting point and captive destination. A normal visit may recover the egg.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="APC tile" style="background-position:-1760px 0"></span><div><h4>APC</h4><p>Your starting vehicle, Med Evac destination and the only place to incinerate an egg.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Staging area tile" style="background-position:-1920px 0"></span><div><h4>Staging area</h4><p>Deliver scientists here, board the Dropship or call for launch.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Gun emplacement tile" style="background-position:-2080px 0"></span><div><h4>Gun emplacement</h4><p>Created by deploying a sentry. Uses open ground movement rules.</p></div></article><article class="manual-tile"><span class="manual-tile-art" role="img" aria-label="Dropship tile" style="background-position:-2240px 0"></span><div><h4>Dropship</h4><p>Parked beyond the staging area. Board through the staging area; the ship is not a separate movement destination.</p></div></article></div></section><section><h3>TERRAIN NOTES</h3><p>Event tiles, bridges, spore fields and Gravity Wells cannot spawn beside another tile of the same type.</p><ul><li>Open ground and gun emplacements: normal movement.</li><li>APC: starting tile, destination for Med Evac, and incinerator for the egg.</li><li>Staging area: deliver scientists, board the Dropship or initiate quarantine for launch. Yellow rotating corner lights activate when two hours remain. Arriving here does not automatically board you: press Board Dropship, then Confirm Boarding, or Cancel to stay on the surface.</li><li>Alien nest: randomly placed on the outer ring each mission, excluding the top and top-right edges. The alien always starts here, and captured Marines are taken here.</li><li>Green/blue Gravity Wells: entering transports you to the other well of the same colour, revealing both. It costs the original move; jetpack landings also use this effect.</li><li>Hard cover: the alien does not select occupants as stalking targets, unless a noise or lure overrides its normal behaviour. Contact can still capture you.</li><li>Spore field: entering creates noise that draws the alien.</li><li>Bridge: normal crossing; can be collapsed by a Seismic Shift event. Players cannot collapse bridges.</li><li>Collapsed tile: impassable to Marines and the alien; unavailable as an equipment target.</li><li>Event tile: triggers a new event every time someone enters, including revisits. It remains an event tile. Only Spore Burst directly ends remaining movement.</li></ul></section>
<section><h3>SEARCH &amp; SCIENTISTS</h3><p>Search a PDT or equipment cache on your own tile for one action. Searches make noise. PDT means Personal Data Transmitter. PDT signals may be fake. Equipment caches and PDTs, including fake PDT signals, never appear on Gravity Wells, the nest, the APC or the Dropship. Equipment needs a free inventory slot; you may carry at most two items.</p><p>You may escort one scientist at a time, separately from inventory. Finding a scientist starts escorting automatically if you are free to do so; arriving at a previously located scientist also starts escorting. Use Escort Scientist for a waiting or dropped scientist when needed; this costs an action. Deliver Scientist costs one action at the staging area. Both scientists must be delivered before launch.</p></section>
<section><h3>ALIEN, CAPTURE &amp; ESCAPE</h3><p>The alien stalks eligible Marines, then attacks after stalking. At round end it moves up to two tiles. Flare signals, noise and secret redirection can change its target; events may cause an extra one-tile movement. Cover and temporary concealment protect against normal targeting, not forced movement or physical contact.</p><p>Contact captures a Marine and takes them to the nest. All carried equipment is permanently lost. An escorted scientist remains where capture occurred. The alien then withdraws.</p><p>A captive may roll the alien d6 once per round. Even: escape with two moves and no action, or one move if still injured by a Facehugger. Odd: remain captive and the turn ends. A free Marine at or adjacent to the nest may spend an action to free another captive. A newly freed Marine is protected from immediate recapture at the nest until leaving it or the round ends.</p></section>
<section id="manual-equipment"><h3>EQUIPMENT &amp; INVENTORY</h3><ul><li>Flare: consume the item, with no action cost, to target a valid tile within three tiles, including your own. It permanently reveals its landing tile and lures the alien this round and next.</li><li>Jetpack: consume the item, with no action cost, to land one to three tiles away, bypassing intervening ground. Landing makes noise and applies the destination terrain effects. A scientist travels with you.</li><li>Bioscanner: consume the item, with no action cost, to add one shared scan charge. The team starts with two charges.</li><li>Med Evac: consume the item, with no action cost, to return immediately to the APC and restore movement after a Facehugger attack. It does not cure impregnation. Inventory and an escorted scientist travel with you; contact with the alien can still capture you.</li><li>Sentry gun: deploy on your tile for no action cost. Cannot deploy on Gravity Wells, collapsed bridges, the alien nest, APC, Dropship or an existing sentry. Replaces terrain with a gun emplacement using open ground rules. Appears just ahead of the Marine on the same tile. Sweeps towards the alien, with a flashing red light while armed; the light switches off after firing. Scans adjacent tiles; its single firing burst destroys an entering alien in translucent yellow-green goo before any report opens. A new alien spawns silently at the nest and waits until its next movement sequence.</li><li>Alien egg: found on a normal visit to the nest, never through capture. Carry it as an inventory item. The crew must keep it off the departing Dropship.</li><li>Chemical Research: consume the item, with no action cost, for a private random result. Adrenal surge (35%): three moves next free turn. Cognitive surge (35%): two actions next free turn. Fatigue (20%): one move next free turn. Neural shutdown (10%): no actions on the next two free turns; movement remains available.</li></ul><p>Dropping an item permanently discards it and costs no action, even after using your action. It cannot be recovered. Capture also permanently removes all carried equipment. At the APC, only the egg can be incinerated; this costs an action and makes noise.</p></section>
<section id="manual-transfer"><h3>SCANNING, PASSING &amp; TAKING</h3><p>Bioscan a free Marine on your own tile, excluding yourself, for one action and one shared charge. The report reveals both equipment slots and any chest anomaly. Scanned item names remain visible to this player when taking equipment until the holder’s inventory changes. Scanning leaves all items with their holder. The egg can only be destroyed by incineration at the APC.</p><p>Pass an item to another Marine on your tile for one action if they have space. Take a selected inventory slot from another free Marine on your own or an adjacent tile for one action if you have space. Item names are hidden until you bioscan their holder. Passing shows your own item names.</p></section>
<section><h3>ALL EVENT EFFECTS</h3><ul><li>Alien Lunge: alien moves one tile towards you.</li><li>Seismic Shift: an eligible empty bridge collapses and its tile is revealed.</li><li>Spore Burst: ends remaining movement, makes noise, and moves the alien one tile towards you.</li><li>PDT Locator: choose to locate a hidden PDT. Fake PDT signals are cleared. Costs one shared scan charge if available; works with none.</li><li>Adrenaline Surge: immediately adds one move, subject to a Facehugger injury.</li><li>Motion Echo: briefly highlights the alien’s position for five seconds after the report closes, subject to the normal discovered-tile visibility rules. It does not reveal terrain.</li><li>Facehugger Attack: privately impregnates you and reduces movement to one tile per turn until Med Evac is used. Med Evac restores mobility but does not cure impregnation. An impregnated passenger aboard means Company victory; staying behind can allow a crew victory.</li></ul><p>All seven events are shuffled into a deck, which reshuffles when empty. Event tiles trigger on every entry and keep their terrain and artwork. Only Spore Burst ends remaining movement outright. Choices must be resolved before continuing. Infection is shown only on the affected player’s tab, with no public announcement.</p></section>
<section><h3>CORPORATION ACTIONS</h3><p>Only the Company Representative may use these private actions; each costs one action and resolves at round end. Jam Scanner removes one shared charge if available. Fake PDT signal plants a decoy on eligible empty ground within one tile; there are two decoys for the mission. Redirect Creature chooses a target up to two tiles away to lure the alien. Public information describes the effects without naming the operative.</p></section>
<section><h3>ALIEN PRESSURE</h3><p>Four Marines face one alien. Five or six Marines face two independently hunting aliens, both starting at the nest. Each takes its own two-move round turn. Flare and noise events attract both; a sentry destroys only the alien it shoots; a replacement spawns silently at the nest. The tracker shows both in-range contacts, with pulse speed determined by the closest.</p></section><section><h3>TRACKER &amp; BIOSUIT</h3><p>The tracker shows contact when the alien is within three tiles of the current Marine. A new contact plays a horror sting; tracker pings every 1.8 seconds at three tiles, 1.1 seconds at two tiles and 0.65 seconds at one tile. Tracker audio continues during reports and private orders; only capture reports pause it. Sound can be muted without removing the blip. On the board, an alien in a discovered tile appears as a glow within two tiles of a free Marine, and as the alien figure when adjacent. An alien on an undiscovered tile appears only on the tracker, even when adjacent.</p><p>The biosuit shows heart rate rising with alien proximity or captivity. Its ECG is a warning display, not an extra action.</p></section>
<section id="manual-launch"><h3>BOARDING, QUARANTINE &amp; EXTRACTION</h3><p>At the staging area, choose Board Dropship to leave surface play until quarantine. Boarded Marines take no further turns. After both scientists are delivered, a free Marine at the staging area may Call for Launch with an action available. Calling launch automatically boards that Marine, even if they are the first passenger. If no free Marines remain, boarded crew can activate quarantine directly. Launch commits the crew to quarantine. No further scans, movement, equipment use or return to the board are allowed. Discuss clearance, then mark each passenger CLEARED or CONTAMINATED using the stacked buttons. Multiple passengers can be contaminated. PURGE CONTAMINATED names the selected crew for confirmation before ejecting them through the airlock and starting departure. If everyone is cleared, launch without ejecting anyone.</p><p>Launch activates only once both scientists are aboard. If any selected passenger carries the egg or is impregnated, the Company wins, regardless of who carries it or whether the Company Representative escapes. Otherwise the crew wins, even if the egg or other Marines remain on the planet. Every player being captured ends the mission immediately with Alien victory. At zero hours, quarantine opens automatically if both scientists and at least one eligible, non-captive Marine are aboard. Otherwise the mission fails.</p><p>The oversized Dropship remains on its terrain tile. The roof amber beacon activates after the two-hours-left countdown closes. Yellow rotating staging lights activate when two hours remain, reaching adjacent tiles without revealing unexplored terrain. After you confirm the purge or all-clear launch, every Marine left behind is placed at the staging area for the final stand. If nobody is left behind, two sentry drones defend it. The Dropship departs as the aliens close in, followed by the orbital scene and mission results.</p><p>Abort Mission leaves the current mission. Closing or reloading the app also ends it: there is no saved-game continuation.</p></section>
</div><div class="order-footer"><button class="order-ack" data-act="closeRules">RETURN TO CREW ROSTER</button></div></div></div>`}
function playablePlayerOption(action,disabled=false){
 if(disabled||!s||ui.boot!=='game'||s.phase!=='play'||s.pendingEvent||ui.sequence||ui.popup||ui.private||ui.flipping||ui.rolling||ui.cinematic||ui.capturePrelude||WristTerminal.isClosing())return false;
 const p=me();if(p.boarded)return false;
 if(action==='scan')return s.ap>0&&s.scans>0&&!p.captive&&scanPeers().length>0;
 if(action==='end')return true;
 if(action==='escape')return p.captive&&p.rolledRound!==s.round;
 if(p.captive)return false;
 if(action==='cancelTarget')return !!ui.mode;
 if(action==='confirmTarget')return !!ui.targetHex&&targetValid(ui.targetHex);
 if(action.startsWith('chooseItem:')){const v=p.cargo[+action.split(':')[1]];return USABLE.includes(v)&&CELLS.some(c=>validItemTarget(v,c.k))}
 if(action.startsWith('drop:')||action.startsWith('research:'))return !!p.cargo[+action.split(':')[1]];
 if(action==='boardDropship')return p.pos===DROPSHIP;
 if(action==='privateActions')return p.role==='companyRepresentative'&&s.ap>0;
 if(action==='transfer')return s.ap>0&&s.players.some((o,i)=>i!==s.turn&&!o.boarded&&!o.captive&&(o.pos===p.pos&&o.cargo.length<2&&p.cargo.length||dist(o.pos,p.pos)<=1&&p.cargo.length<2&&o.cargo.length));
 if(action==='launch')return s.ap>0&&canLaunch();
 return s.ap>0;
}

// TEMPORARY TEST NAVIGATION: remove this block and its CSS after testing.
const TEST_NAVIGATION=true;
const TEST_SECTIONS=[['intro','Intro'],['crew','Crew'],['title','Title'],['board','Board'],['handoff','Pass iPad'],['male','Capture M'],['female','Capture F'],['countdown','Countdown'],['quarantine','Quarantine'],['battle','Battle'],['sentryBattle','Sentry Battle'],['failed','Failed Battle'],['orbit','Orbit'],['results','Failed Result']];
function syncTestNavigation(){
 if(!TEST_NAVIGATION)return;document.body.classList.add('has-test-nav');
 let bar=document.getElementById('test-navigation');if(!bar){bar=document.createElement('nav');bar.id='test-navigation';bar.setAttribute('aria-label','Temporary game test navigation');bar.innerHTML='<span>TEST</span>'+TEST_SECTIONS.map(([id,label])=>`<button type="button" data-test-section="${id}">${label}</button>`).join('');document.body.append(bar);bar.addEventListener('click',e=>{const button=e.target.closest('[data-test-section]');if(button)testJump(button.dataset.testSection)});}
}
async function testJump(section){
 if(!TEST_NAVIGATION)return;if(tutorial)exitTutorial();
 if(soundOn)audioSafely(()=>safeAudioUnlock(false));
 const roster=s?.players?.map(p=>({name:p.name,voice:p.voice}))||ui.roster||[];
 clearTimeout(cinemaTimer);cinemaTimer=null;cinemaNext=null;cinemaRemaining=0;clearTimeout(ui.introEndTimer);ui.loginEndCancel?.();ui.titleGlowAnimation?.cancel();ui.titleZoomAnimation?.cancel();stopAPCTransmission();stopTerminal();WristTerminal.cancel();window.ShipLastStand?.stop();
 const pendingPopup=popupRun;popupRun=null;if(pendingPopup)pendingPopup.resolve();
 s=null;resumeExpiredWaits();
 for(const key of ['roundCountdown','finalBattle','endCredits','maleCapture','femaleCapture','tracker','wristDrone','apc','muthurLogin','chances','muthurOff','titleDrone','ripley','start'])audioSafely(()=>ShipAudio.stopEffect(key));
 newGame([0,1,2,3].map(i=>roster[i]?.name||`TEST MARINE ${i+1}`),[0,1,2,3].map(i=>roster[i]?.voice||'male'),true);
 const game=s;ui.note='TEST PREVIEW — fresh sample mission';
 if(section==='intro'){s=null;ui.boot='boot';ui.introActivated=false;render();return}
 if(section==='crew'){s=null;ui.boot='roster';ui.roster=[0,1,2,3].map(i=>({name:roster[i]?.name||`TEST MARINE ${i+1}`,voice:roster[i]?.voice||'male'}));render();return}
 if(section==='title'){s.backgroundStarted=false;ui.cinematic=true;if(soundOn)audioSafely(()=>{ShipAudio.play('ripley',1,5);ShipAudio.play('titleDrone',1,5)});cinemaStage('title');return}
 if(section==='board'){render();return}
 if(section==='handoff'){s.phase='handoff';render();return}
 if(section==='male'||section==='female'){const hex=Object.keys(s.tiles).find(k=>s.tiles[k].terrain==='open');s.players[0].pos=hex;s.players[0].voice=section;s.tiles[hex].known=true;s.alien=hex;capture();finish();return}
 s.players.forEach((p,i)=>{p.boarded=i<2;p.captive=false;p.pos=DROPSHIP});s.delivered=section==='failed'||section==='countdown'||section==='results'?1:2;
 if(section==='quarantine'){openQuarantine();return}
 if(section==='countdown'){ui.sequence=true;await roundCountdown(0);if(s!==game)return;ui.sequence=false;beginDeparture(departurePlan([0,1],true));return}
 if(section==='sentryBattle'){s.players.forEach(p=>p.boarded=true);const hex=Object.keys(s.tiles).filter(k=>k!==DROPSHIP&&s.tiles[k].terrain==='open').sort((a,b)=>dist(a,DROPSHIP)-dist(b,DROPSHIP))[0]||HOME;s.tiles[hex].terrain='open';s.tiles[hex].emplacement=true;s.tiles[hex].known=true;s.sentries=[{hex,armed:true,deployFacing:0,aim:0,firingUntil:0}];beginDeparture(departurePlan([0,1,2,3],true));return}
 const plan=departurePlan([0,1],true);
 if(section==='battle'||section==='failed'){beginDeparture(plan);return}
 s.departure={...plan,ejected:[],started:performance.now()-51000,contacts:[]};s.phase=section==='results'?'over':'orbital';s.winner=section==='results'?'failed':null;ui.orbitalAt=performance.now();render();
}
function highlightPlayerOptions(){document.querySelectorAll('.side .flip-front button[data-act]').forEach(button=>{button.classList.toggle('playable-option',playablePlayerOption(button.dataset.act,button.disabled))})}
let tutorial=null;
const TUTORIAL_STEPS=[
 ["How to play","The Last Ship is a pass-and-play game for between 4–6 players. Players take turns using the same iPad, keeping the iPad hidden from the other players when it’s your go. If you’re playing connected mode, then make sure they can’t see your phone.",["tutorialNext"],null,null],
 ["Your mission","Your mission is to rescue both scientists and escape aboard the dropship, while preventing the alien organism from leaving the planet.\n\nBut beware: one of you is secretly working for the Company and will do whatever it takes to ensure its orders are carried out.\n\nWork together—but be careful who you trust.",["tutorialNext"],null,null],
 ["Identify yourself","Press the fingerprint button to open your player terminal.",['fingerprint'],null,()=>s.phase==='play'],
 ["Move and reveal","Tap the yellow highlighted tile. You have two moves each turn; moving to an undiscovered tile reveals it.",[],'1,0',()=>me().pos==='1,0'],
 ["Search the cache","You also have one action per turn. Some tiles can be searched, which uses up your action. Press Search Equipment.",['search'],null,()=>me().cargo.includes('flare')],
 ["Use equipment","Press Acknowledge, then press Use Flare in your inventory. Using equipment does not spend an action.",['chooseItem:0'],null,()=>ui.mode==='itemTarget'],
 ["Choose a target","Tap the yellow highlighted tile. Flares can be thrown up to three tiles away.",[],'0,1',()=>ui.targetHex==='0,1'],
 ["Confirm the flare","Press Confirm target. The flare reveals its tile and lures the alien for this round and the next.",['confirmTarget'],null,()=>s.flares.length>0],
 ["End your turn","Press End turn. Unused moves and actions are lost; the terminal shuts down before you hand the iPad to the next player.",['end'],null,()=>s.phase==='handoff'&&s.turn===1],
 ["Pass the iPad","The next player presses the fingerprint button and takes their turn. After all players have had their turn, the alien then moves and the round ends. An hour passes every round.",['fingerprint'],null,()=>s.phase==='play'&&s.turn===1],
 ["Prepare a sentry","Each player starts with a different item in their inventory depending on their role. This Marine has a sentry gun. Lucky them. Press the Use Sentry Gun button.",['chooseItem:0'],null,()=>ui.mode==='itemTarget'],
 ["Deploy the sentry","Press Confirm to deploy the sentry gun on your current tile. The sentry covers adjacent tiles, firing one burst of bullets. Let’s hope that’s enough, because that’s all it’s got.",["confirmTarget"],null,()=>!!tutorial.sentryDemoDone],
 ["Read the tracker","The motion tracker (bottom right) picks up nearby movement, which is lucky because the aliens can be hidden on undiscovered tiles.\n\nThe Motion Echo perk marks the location of the alien for the rest of the round.\n\nNow let’s use the Bioscanner.",['tutorialNext'],null,null],
 ["Bioscan your teammates","Sharing a tile with another Marine? You can bioscan them to check their equipment and look for signs of impregnation. A scan uses your action and one shared scan charge. Use them wisely—you may uncover something they’d rather keep hidden. Press the Bioscanner button and select your teammate.",["scan","scan:0"],null,()=>!!s.scanKnowledge?.[s.turn]?.[0]],
 ["Check the results","So you probably wouldn’t want that Marine leaving on the dropship. Press Acknowledge.",["closeSearchPopup"],null,()=>!!tutorial.bioscanAcknowledged],
 ["Find the Scientists","Tap the yellow highlighted tile. The blue icon that pops up is a Personal Data Transmitter (PDT) signal and can give us the location of the unfortunate scientists.",[],'2,0',()=>me().pos==='2,0'],
 ["Locate the PDT signal","Press the Locate PDT signal button.",['search'],null,()=>me().scientist],
 ["Get them to the dropship","Be aware you may come across false PDT signals as well. You can only escort one scientist at a time. If you get caught by the alien, the scientist will run and hide behind a rock or something and stay in the tile where you were captured. Now press Acknowledge then follow the yellow highlighted route to the staging area next to the dropship.",[],()=>me().pos==='2,0'?'2,-1':'3,-2',()=>me().pos===DROPSHIP],
 ["Deliver the scientist","Press Deliver scientist, then Acknowledge. Both scientists must be aboard to complete your mission.",['deliver'],null,()=>s.delivered===1],
 ["Board the dropship","Now press Acknowledge and then press Board Dropship, then press Confirm Boarding. Boarding the dropship takes you off the board and ends all your turns. You are safe… for now.",['boardDropship','confirmBoarding'],null,()=>s.players[1].boarded],
 ["Quarantine Protocol","The Marines have now delivered the second scientist and boarded the dropship. Press Activate Quarantine protocols. You could have also just delivered a scientist to the dropship without boarding and then headed back out into the field to help your team.",['launch'],null,()=>s.phase==='quarantine'],
 ["Who looks suspicious.","Now discuss as a team who you think may be working for the Company, or who you think may have fallen victim to a facehugger. Then either clear all your team for takeoff or press Contaminated for the ones you don’t trust.\n\nThis lot onboard are all cleared, so select Cleared for each Marine.\n\nThen press the All Cleared - Launch button.\n\nAnd away they go…",["grantClearance:0","grantClearance:1","grantClearance:2","grantClearance:3","depart"],null,null],
 ["Win or Lose","Once you’ve pressed the launch/purge button, you have finished your mission—but were you successful? Leaving without both scientists fails the mission. An egg or impregnated passenger aboard fails the Marines’ mission but is a win for the Company. So either way someone wins… unless no one makes it back, of course.",["tutorialNext"],null,null],
 ["Working for the Company","Now this is the sneaky bit. At the start of round two, one Marine secretly becomes the Company Representative. If that’s you, your player will receive some Company orders. Press Acknowledge and your player screen will reboot in a cool (I’m so evil) red colour. Keep your orders and player screen hidden from the other players.",["closePrivate"],null,()=>!ui.private&&!ui.companyIntro],
 ["Special Order 937","The Company wants the alien organism brought back for analysis. To secure the Company’s win, both scientists and at least one Marine must escape with an alien egg or an impregnated passenger aboard. The unfortunate impregnated Marine doesn’t have to be you.",["tutorialNext"],null,null],
 ["Private actions","Press Private actions to reveal your secret options. Each uses your action for that turn, so choose carefully. Their effects happen at the end of the round without revealing who caused them.",["privateActions"],null,()=>ui.privateKind==='actions'],
 ["Disable a scan charge","Bioscans could expose what you’re carrying. Press Disable one scan charge. If the team has two charges remaining, this can leave them with just one at the end of the round, and the tricky decision of who to scan.",["jam"],null,()=>s.pendingSabotage.some(x=>x.type==='jam')],
 ["Plant a fake PDT signal","A fake PDT signal can send your teammates searching in the wrong place. Press Plant fake PDT signal, select the yellow highlighted tile, then Confirm target. The fake signal appears at the end of the round. You have two decoy uses.",["decoy", "confirmTarget"],'0,1',()=>s.pendingSabotage.some(x=>x.type==='decoy')],
 ["Redirect the creature","Use the alien to disrupt the rescue. Press Redirect the creature, select the yellow highlighted tile, then Confirm target. At the end of the round, the alien is drawn towards that location. Try choosing somewhere near another Marine—but remember, it doesn’t guarantee an attack.",["redirect", "confirmTarget"],'0,-1',()=>s.pendingSabotage.some(x=>x.type==='redirect')],
 ["Return to your terminal","Press Acknowledge to return to your player tab.\n\nHelp the team enough to earn their trust, but remember whose orders you’re really following.",["closePrivate"],null,()=>!ui.private],
 ["Getting the organism aboard","You can visit the nest during a normal turn to collect an egg. But being captured won’t give you one. And if you have an egg and get captured by the alien, you lose the egg and will have to go back to get another one.",["tutorialNext"],null,null],
 ["Keep it hidden","Keep it hidden: another Marine on your tile can bioscan you, which will reveal the egg, but the egg can only be incinerated at the APC.\n\nAt quarantine, the egg or impregnated passenger must remain aboard for the Company to win.\n\nSo be persuasive, and try not to act too suspicious.",["tutorialNext"],null,null],
 ["Training complete","You have practised the Marines’ controls and the evil Company’s actions. Now return to crew registration, Marine, to begin your mission. Move it! Move it! Move it… absolute badasses!",["tutorialExit"],null,null],
];
function startTutorial(){if(ui.boot!=='roster')return;rememberRoster();const roster=ui.roster.map(r=>({...r}));audioSafely(()=>safeAudioUnlock(false));newGame(['TRAINING SGT','TRAINING TECH','TRAINING MEDIC','TRAINING SCIENCE'],['female','male','female','male'],true);tutorial={game:s,step:0,roster};s.companyAssigned=true;s.nest='-3,0';s.alien=s.nest;s.extraAliens=[];s.alienMind={mode:'idle',target:null,stalked:0};s.flares=[];s.sentries=[];s.events=[];for(const[k,t]of Object.entries(s.tiles)){Object.assign(t,{terrain:k===HOME?'lander':k===DROPSHIP?'dropship':k===s.nest?'nest':'open',known:[HOME,DROPSHIP,s.nest].includes(k),pair:null,site:null,loose:[],groundScientists:0,emplacement:false})}s.tiles['1,0'].site={kind:'cargo',value:'flare',status:'hidden'};s.tiles['2,0'].site={kind:'distress',value:'scientist',scientistId:0,status:'hidden'};s.players.forEach(p=>{p.briefed=true;p.cargo=[]});s.players[1].cargo=['sentry'];s.phase='handoff';render()}
async function tutorialSentryDemo(){return trackedSequence(tutorialSentryDemoInner,[])}
async function tutorialSentryDemoInner(){
 const lesson=tutorial,game=s;ui.sequence=true;
 try{
  const gun=s.sentries.at(-1),[gx,gy]=hexCentre(gun.hex);
  const target=adjacent(gun.hex).filter(k=>hexCentre(k)[1]<gy).sort((a,b)=>Math.abs(hexCentre(a)[0]-gx)-Math.abs(hexCentre(b)[0]-gx))[0];
  const from=adjacent(target).filter(k=>k!==gun.hex&&hexCentre(k)[1]<hexCentre(target)[1]).sort((a,b)=>hexCentre(a)[1]-hexCentre(b)[1])[0]||s.nest;
  tile(from).known=true;tile(target).known=true;s.alien=from;s.alienSpawnHidden=false;
  const oldFacing=alienFacing();s.alienFacing=heading(from,target);ui.alienMotion={from,to:target,started:Date.now(),duration:1000,oldFacing};ui.alienLastFacing=s.alienFacing;render();
  await pause(1000);if(s!==game||tutorial!==lesson)return;
  ui.alienMotion=null;s.alien=target;await fireSentry(target);
  if(s===game&&tutorial===lesson)lesson.sentryDemoDone=true;
 }finally{if(s===game&&tutorial===lesson){ui.sequence=false;ui.alienMotion=null;finish()}}
}
function tutorialPrepare(){const title=TUTORIAL_STEPS[tutorial.step][0];
if(title==='Prepare a sentry'){me().pos='1,0';s.tiles['1,0'].known=true}
if(title==='Bioscan your teammates'){s.ap=1;s.scans=2;tutorial.bioscanAcknowledged=false;const p=s.players[0];p.cargo=['egg'];p.impregnated=true;p.boarded=false;p.captive=false}
if(title==='Find the Scientists'){s.players[0].cargo=[];s.players[0].impregnated=false;me().pos='1,0';s.tiles['1,0'].known=true;s.moves=2;s.ap=1;s.movesTaken=0;s.turnMoveBudget=2}
if(title==='Get them to the dropship'){s.moves=2;s.ap=1;s.movesTaken=0;s.turnMoveBudget=2}
if(title==='Quarantine Protocol'){s.delivered=2;s.players.forEach(p=>{p.boarded=true;p.pos=DROPSHIP});s.phase='readyLaunch';ui.mode='';ui.private=false}
if(title==='Working for the Company'){s.phase='play';s.round=2;s.turn=1;s.quarantine=null;s.players.forEach(p=>{p.boarded=false;p.pos=HOME});me().pos='1,0';me().role='companyRepresentative';me().briefed=false;s.ap=1;s.moves=2;s.scans=2;s.decoys=2;s.pendingSabotage=[];ui.mode='';ui.private=true;ui.privateKind='briefing';ui.companyIntro=true;ui.flipping='';ui.note=''}
if(['Disable a scan charge','Plant a fake PDT signal','Redirect the creature','Return to your terminal'].includes(title)){s.ap=1;ui.private=true;ui.privateKind='actions';ui.mode='';ui.targetHex=null}
}

// Completed lessons follow game state even while the CRT closes; waiting here can strand boarding at handover.
function tutorialAdvance(){if(!tutorial)return;if(s!==tutorial.game){tutorial=null;return}if(ui.popup||ui.sequence||ui.flipping||ui.handoffLoading)return;const step=TUTORIAL_STEPS[tutorial.step];if(step[4]?.()){tutorial.step++;tutorialPrepare()}}
function exitTutorial(){if(!tutorial)return;const roster=tutorial.roster;tutorial=null;const pending=popupRun;popupRun=null;pending?.resolve();s=null;resumeExpiredWaits();WristTerminal.cancel();window.ShipLastStand?.stop();window.ShipTerrain?.stop();audioSafely(()=>{ShipAudio.gameLoop(false);for(const key of ['finalBattle','endCredits','wristDrone','rescued','discovery','scientistFound'])ShipAudio.stopEffect(key)});ui={boot:'roster',roster,nameEdit:0};render()}
function tutorialAction(a){
if(a==='startTutorial'){startTutorial();return true}if(!tutorial)return false;
const step=TUTORIAL_STEPS[tutorial.step];
if(a==='tutorialExit'){exitTutorial();return true}
if(a==='depart'&&step[0]==='Who looks suspicious.'){
 if(!s.quarantine?.eligible.every(i=>s.quarantine.cleared.includes(i)))return true;
 s.phase='play';s.quarantine=null;tutorial.step++;tutorialPrepare();render();return true
}
if(a==='closeSearchPopup'&&step[0]==='Check the results'&&ui.popup?.kind==='bioscan')tutorial.bioscanAcknowledged=true;
if(a==='tutorialNext'){if(step[2].includes('tutorialNext')&&!ui.popup&&!ui.sequence&&!ui.flipping){tutorial.step++;tutorialPrepare();render()}return true}
if(['toggleSound','closeSearchPopup','closePrivate','ackResults'].includes(a))return false;
if(a==='abortMission'){exitTutorial();return true}
return !step[2].includes(a)
}

function tutorialMount(){document.querySelector('.tutorial-guide')?.remove();document.querySelectorAll('.tutorial-highlight').forEach(n=>n.classList.remove('tutorial-highlight'));if(!tutorial)return;const step=TUTORIAL_STEPS[tutorial.step];const guide=document.createElement('section');guide.className='tutorial-guide';guide.setAttribute('aria-label','Guided tutorial');guide.innerHTML=`<small>TRAINING · ${tutorial.step+1}/${TUTORIAL_STEPS.length}</small><strong>${step[0]}</strong><p>${esc(step[1]).replace(/\n\n/g,'<br><br>').replace(/\n/g,'<br>')}</p><div>${step[2].includes('tutorialNext')?'<button data-act="tutorialNext">ACKNOWLEDGE</button>':''}<button data-act="tutorialExit">${tutorial.step===TUTORIAL_STEPS.length-1?'RETURN TO CREW ROSTER':'SKIP TUTORIAL'}</button></div>`;document.getElementById('app').append(guide);if(ui.popup||ui.sequence||ui.flipping)return;for(const a of step[2])document.querySelectorAll(`[data-act="${a}"]`).forEach(n=>n.classList.add('tutorial-highlight'));const target=typeof step[3]==='function'?step[3]():step[3];if(target)document.querySelectorAll(`[data-hex="${target}"]`).forEach(n=>n.classList.add('tutorial-highlight'))}

function apateRosterSchematic(){return `<aside class="apate-roster" aria-label="UKSS APATE pre-flight systems"><strong>UKSS APATE · PRE-FLIGHT SYSTEM CHECK</strong><img class="apate-schematic-image" src="apate-schematic.webp" alt="UKSS APATE dropship schematic showing engine nacelles, cockpit and troop compartment" width="1536" height="1024"><div class="apate-readout"><div>ENGINES: STANDBY</div><div>CREW: ${ui.roster.length} REGISTERED</div><div>MISSION: AWAITING LAUNCH</div><small><span class="apate-status">●</span> PERSONNEL LINK ACTIVE</small></div></aside>`}
function render(){tutorialAdvance();audioSafely(syncQuarantineAudio);audioSafely(syncEndingAudio);if(ui.boot==='game')document.getElementById('app').classList.remove('intro-malfunction','intro-crt-off','fade-black','long-fade','intro-roster-fade');renderContent();highlightPlayerOptions();WristTerminal.sync(ui,s,soundOn);syncTestNavigation();tutorialMount()}
